'use strict';
// REF GEAR — the reference hero's outfit on the ref rig (models/ref.js): red scarf + cape, round red shield (left arm),
// short sword (right hand). Exact reference colours; the sword blade is a 1 px line (white, like the reference), and the
// sword's smear (attack frames 1-3) is generated by forge.js from the hand -> tip path, one flat tone, no outline.
const NAVY = '#1f2357';
const RED = { ramp: ['#670948', '#a62144', '#a62144', '#a62144'], tones: [0.9, 0.5, -0.35] };
const notAttack = fn => (a, f) => a.startsWith('attack') ? {} : fn(a, f);

const cape = {
  id: 'cape', slot: 'back',
  layers: [{ id: 'cape', mats: { cloth: RED }, prims: [
    { bone: 'chest', mat: 'cloth', part: 'scarf', shape: 'ell', c: [0, 4.3, 0.2], r: [3.1, 1.3, 2.7] },
    { bone: 'chest', mat: 'cloth', part: 'scarf', shape: 'ell', c: [0, 3.0, 2.0], r: [2.2, 1.8, 0.9] },
    { bone: 'cape', mat: 'cloth', part: 'cape', shape: 'cap', a: [0, -0.3, -0.3], b: [0, -8.8, -1.0], ra: 3.0, rb: 3.5, clip: [[0, 1, 0, 0], [0, -1, 0, 9.0]] },
  ] }],
  pose: () => ({ cape: { scl: [1, 1, 0.25] } }),
};

const shield = {
  id: 'shield', slot: 'offhand',
  layers: [{ id: 'shield', mats: {
    face: RED, back: { ramp: ['#592104', '#592104', '#a64e21', '#a64e21'], tones: [0.95, 0.3, -2] },
    rim: { ramp: ['#a64e21', '#a64e21', '#cc7c52', '#e5e0ac'], tones: [0.55, 0.0, -0.6] },
    boss: { ramp: ['#cc7c52', '#cc7c52', '#e5e0ac', '#e5e0ac'], tones: [0.9, 0.2, -2] },
  }, prims: [
    { bone: 'offhand', mat: 'back', part: 'shield', shape: 'ell', c: [0, 0.2, 0.35], r: [3.4, 3.4, 0.45] },
    { bone: 'offhand', mat: 'rim', part: 'shield', shape: 'ell', c: [0, 0.2, 0.75], r: [3.7, 3.7, 0.4] },
    { bone: 'offhand', mat: 'face', part: 'shield', shape: 'ell', c: [0, 0.1, 1.05], r: [3.0, 3.0, 0.5] },
    { bone: 'offhand', mat: 'boss', part: 'shield', shape: 'ell', c: [0, 0.1, 1.55], r: [0.8, 0.8, 0.45] },
  ] }],
  pose: a => ({ offhand: a === 'walk' ? { aim: [0.05, 1, 0.05], roll: [0.6, 0, 0.8] } : { aim: [0.05, 1, 0], roll: [0.55, 0, 0.83] } }),
};

const sword = {
  id: 'sword', slot: 'weapon', class: 'sword', smear: '#fafaf6',
  layers: [{ id: 'sword', mats: { blade: { ramp: ['#fafaf6', '#fafaf6', '#fafaf6', '#fafaf6'], flat: 0 }, hilt: { ramp: ['#a64e21', '#a64e21', '#ba8a38', '#ba8a38'], tones: [0.9, 0.2, -2] } },
    prims: [
      { bone: 'weapon', mat: 'hilt', part: 'hilt', shape: 'cap', a: [0, -0.9, 0], b: [0, 1.0, 0], ra: 0.6, rb: 0.6 },
      { bone: 'weapon', mat: 'blade', part: 'blade', shape: 'line', a: [0, 1.2, 0], b: [0, 8.6, 0], conn4: true },
    ] }],
  sockets: { tip: { bone: 'weapon', at: [0, 8.6, 0] } },
  pose: notAttack((a, f) => ({ weapon: { aim: a === 'walk' && f < 2 ? [-0.75, -0.1, -0.65] : [-0.3, 0.85, 0.42] } })),   // the run trails it on 0-1
};

const pieces = { cape, shield, sword };
const loadouts = { base: [], hero: ['cape', 'shield', 'sword'] };
module.exports = { pieces, loadouts, NAVY };
